const axe = require('axe-core');
const fs = require('fs');
const path = require('path');
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 1366, height: 900 } });
  await page.setContent(fs.readFileSync(path.resolve('index.html'), 'utf8'), { waitUntil: 'load' });
  await page.addScriptTag({ content: axe.source });
  const results = await page.evaluate(async () => await window.axe.run(document, {
    resultTypes: ['violations', 'incomplete']
  }));
  await browser.close();
  const wcag = results.violations.filter(v => !(v.tags || []).includes('best-practice'));
  const bp = results.violations.filter(v => (v.tags || []).includes('best-practice'));
  console.log(JSON.stringify({
    wcag: wcag.map(v => ({ id: v.id, impact: v.impact, targets: v.nodes.map(n => n.target) })),
    bestPractice: bp.map(v => ({ id: v.id, impact: v.impact, targets: v.nodes.map(n => n.target) }))
  }, null, 2));
  process.exit(wcag.length ? 1 : 0);
})().catch((error) => {
  console.error(error.message);
  process.exit(2);
});
